 binding={'policy_version':4,'package_hash':ph,'batch_hash':digest(original),'source_hash':digest(source),'inventory_hash':digest(inventory),'assets':{},'effective_difficulty':'moderate','engine_hash':digest(engine_files)}
 save('reviewed-inputs.json',{'binding':binding,'engine_files':engine_files,'basis':6415,'batch_count':5,'batch_seed':3750266970,'source_material_sha256':source['source_sha256'],'review_policy':'generate/pipeline/reviewer.md','review_policy_file_sha256':rawhash(REPO/'generate/pipeline/reviewer.md'),'provenance':'Independent review by /root/tangent_independent_review; candidate package never edited. Native grader and actual UI renderer run locally; no publication or database mutations.'})
