 for r in read(OUT/'math-samples.json'):m.validate_generated_record(r)
 render=read(OUT/'render/rendering.json');irrelevant=read(OUT/'render-irrelevant/rendering.json')
 assert render['passed'] and irrelevant['passed']
 save('render-inspection.json',{'passed':True,'shared_boundary_validator':str(shared.relative_to(REPO)),'validator_sha256':rawhash(shared),'validated_records':54,'screenshots_inspected':['render/question-001.png','render/question-002.png','render/question-003.png','render/question-004.png','render-irrelevant/question-001.png'],'observations':['All intended equations and aligned rows are visible; conjugate multiplication and final values are legible.','Degree/radian prompts, italic Hint label, all five radio choices and solution panel render correctly.','The source q-43382 final term reorder appears explicitly.','The controlled relevant pair uses the same choice values with a different target and key; the irrelevant unit-change case retains the exact value.','No exposed TeX delimiters, code-trapped mathematics, missing rows or visible emphasis stars.'],'limits':['Five representative UI captures, not screenshots of every catalog instance.','UI preview intentionally selects the key and reveals the worked solution; native grader tests separately exercise every correct/incorrect option.']})
 # Explicit probe success is defined as a uniquely determined key, not a guess
