 regressions=read(OUT/'shortcut-regressions.json');catalog=read(OUT/'catalog.json');probes=[]
 def append(cue,group,scope,strategy,correct,total,baseline,conclusion,refs,disposition='not_predictive'):
  probes.append(dict(cue=cue,subgroup=group,scope=scope,strategy=strategy,correct=correct,total=total,baseline=baseline,disposition=disposition,conclusion=conclusion,sample_refs=refs))
 for name in ['requested','fresh','catalog']:
  p=regressions[name];refs=['shortcut-regressions.json',name+'.json']
  append('Fraction-free ±2 ± sqrt(3) syntactic singleton',name,'within_template','Inspect option text only, without target/key/catalog. Select only if exactly one option has this literal form; otherwise abstain.',p['unique_shape'],p['count'],0.2,'Zero uniquely selected answers; every repaired bank contains two equally shaped possible exact keys. Baseline 0.2 is an uninformed five-choice guess; abstention is not scored as a wrong guess.',refs)
  append('Quadrant and coarse |tan|<1 bounds',name,'within_template','Use only target quadrant and its location relative to 45 degrees modulo 180; compare all option numeric intervals. Select only a sole interval match.',p['unique_interval'],p['count'],0.2,'Zero uniquely selected keys; each target interval contains a plausible wrong competitor. Baseline is random selection among five choices.',refs)
  append('Fraction-free formatting after coarse bounds',name,'within_template','Use the same coarse target bounds and discard displayed fractions, without assuming exact-family constants.',p['unique_fraction_free_interval'],p['count'],0.2,'Zero singleton successes. At least two fraction-free choices remain in the right interval.',refs)
  append('Exact answer family combined with bounds',name,'within_template','Assume the correct value is one of ±2±sqrt(3), then identify its unique sign/magnitude interval.',p['combined'],p['count'],0.2,'This succeeds but imports the complete exact outcome family. It also succeeds on both original banks. Four distinct values occupy four different intervals, so a unique-key radio bank cannot defeat this conjunction without changing the task. Baseline 0.2 is a five-option guess; this outcome is retained as a finite-family learning limitation, not claimed repaired.',refs+['finite-family-analysis.json'],'intended_skill')
 for unit in ['degrees','radians']:
  for op in ['+','-']:
   rows=[r for r in catalog if r['generation']['parameters']['unit']==unit and r['generation']['parameters']['operation']==op]
   counts=Counter(choices(r).index(key(r)) for r in rows)
   append('Fixed answer position',unit+'/'+op,'other_recognizable_subgroup','Choose the most frequent displayed-input position within this subgroup; this is a generous post-hoc upper bound for any fixed-position guess.',max(counts.values()),len(rows),0.2,'All five positions occur; observed maximum is sampling imbalance, not a deterministic position rule. The actual UI independently hashes choice order. Baseline is 1/5.', ['coverage.json','catalog.json','render-inspection.json'])
 for unit in ['degrees','radians']:
  for op in ['+','-']:
   rows=[r for r in catalog if r['generation']['parameters']['unit']==unit and r['generation']['parameters']['operation']==op]
   append('Shape or interval singleton within visible template',unit+'/'+op,'other_recognizable_subgroup','Apply the independent syntactic-only and bounds-only probes separately in this recognizable unit/operation subgroup.',sum(probe(r)['shape_candidates']==1 or probe(r)['interval_candidates']==1 for r in rows),len(rows),0.2,'Both probes have zero singleton success in this subgroup; aggregate results do not hide a conditional perfect cue. Baseline is a five-choice guess.',['catalog.json','shortcut-regressions.json'])
 variation={'learner_operation':'Use the supplied angle decomposition, choose the correct tangent identity, substitute signed special-angle values, and rationalize to select the exact result.','fixed_features':[{'feature':'Five-option exact-value radio response and supplied angle decomposition.','justification':'Both standalone examples provide this contract; the target skill is evaluation, not discovering a decomposition.'},{'feature':'Special-angle operands, nonstandard first-revolution targets, and fraction-free radical answers.','justification':'The canonical/tutorial methods and signed unit-circle prerequisites support these operations. They give four unique exact outcome values, a finite family whose limits are retained.'}],'answer_roles':[{'role':'Which exact result is correct.','eligible_variation':'Four exact values determined by the angle; both signs and magnitude intervals.','observed':'Every class appears in requested five and fresh eight; catalog covers each of eight angles 16 times.'},{'role':'Which choice positions and bank members are keyed.','eligible_variation':'Shuffle positions and construct symmetric two-possible-key banks with wrong competitors.','observed':'All positions occur in each visible unit/operation subgroup; identical-bank counterfactual changes the keyed member.'}],'coverage':[{'case':'Finite catalog and requested batch','sample_refs':['coverage.json','catalog.json','requested.json'],'result':'128 supported decompositions; four unit/operation subgroups of 32; requested five include all four exact results.'},{'case':'Original standalone profiles and canonical example','sample_refs':['source-replays.json','source-replay-results.json'],'result':'Complete source banks preserved only in replay profiles; CLI practice uses repaired extension bank. Canonical difference method reproduced.'}],'counterfactuals':[{'kind':'relevant','change':'Keep all five exact option values and input order fixed; change 15 degrees to 105 degrees and its supplied decomposition.','expected':'Correct choice changes from 2-sqrt(3) to -2-sqrt(3), with matching new worked derivation.','observed':'Both choice sets are identical; exact math, native grader and actual UI accept the changed target/key relationship.','status':'passed','justification':'Changing target evidence must change the tangent; same bank prevents bank-only determination.','sample_refs':['counterfactuals.json','grader-result.json','render/question-001.png','render/question-004.png']},{'kind':'irrelevant','change':'Rewrite the same target and supplied decomposition in radians rather than degrees while preserving bank values.','expected':'Exact result remains 2-sqrt(3), and shown unit conversions do not change the tangent.','observed':'Exact math and native grader agree; actual UI pi/12=5pi/6-3pi/4 displays the same keyed value and worked steps.','status':'passed','justification':'Angle units are representational, not a different geometric angle. Both units are supported by source examples.','sample_refs':['counterfactuals.json','grader-result.json','render-irrelevant/question-001.png']}],'shortcut_probes':probes,'delivery':{'stages_examined':['finite sampler and explicit rejection','requested moderate difficulty','actual shared publication normalization and deduplication','actual learner-selection code and conditional band distribution','actual UI choice ordering'],'sample_refs':['delivery-analysis.json','delivery-requested/delivery.json','delivery-fresh/delivery.json','coverage.json'],'result':'Requested 5/5 and fresh 8/8 survive against basis 6415 with identical per-record decision probes; weighted selection is uniform within available moderate identities and does not inspect key shape.'},'limitations':['The four exact values can be memorized; a learner who knows them plus coarse bounds can answer without recomputing the formula. The combined probe still succeeds and is not hidden.','A finite sample cannot rule out every possible learned shortcut.','Live history can remove identities and change available outcome frequencies; this review binds the captured input pool, not future task draws.','Standalone source worked solutions and key links are absent in capture; exact keys and method are reconstructed from canonical/tutorial evidence.']}
 save('pedagogical-variation.json',variation)
